/// Builds the component record for one nested entry, or returns `nil`
/// when the entry is not a component. A component is a directory package
/// (`.app`/`.framework`/`.bundle`) or a `.pkg`/`.dmg` artifact file.
/// Directory components are measured by a dedicated traversal of the
/// package interior under the same rules as the main scan (hidden
/// entries skipped, nested packages not descended into, symlinks counted
/// without bytes); any unreadable item fails the whole scan, exactly as
/// in the main traversal.
private func component(for url: URL,
                       values: URLResourceValues,
                       root: URL,
                       keys: Set<URLResourceKey>,
                       manager: FileManager) throws -> ArtifactComponent? {
    let isDirectoryComponent = values.isDirectory == true && ["app", "framework", "bundle"].contains(url.pathExtension.lowercased())
    let isFileComponent = values.isRegularFile == true && ["pkg", "dmg"].contains(url.pathExtension.lowercased())
    guard isDirectoryComponent || isFileComponent else { return nil }

    var regularFiles = 0
    var symbolicLinks = 0
    var bytes: UInt64 = 0

    if isFileComponent {
        // A pkg/dmg artifact file is the whole component: one regular
        // file carrying its own bytes.
        regularFiles = 1
        bytes = UInt64(max(values.fileSize ?? 0, 0))
    } else {
        var enumerationError: URL?
        guard let enumerator = manager.enumerator(
            at: url,
            includingPropertiesForKeys: Array(keys),
            options: [.skipsHiddenFiles, .skipsPackageDescendants],
            errorHandler: { failedURL, _ in
                enumerationError = failedURL
                return false
            }
        ) else {
            throw ArtifactScannerError.unreadable(url.path)
        }

        while let item = enumerator.nextObject() as? URL {
            let itemValues: URLResourceValues
            do {
                itemValues = try item.resourceValues(forKeys: keys)
            } catch {
                throw ArtifactScannerError.unreadable(item.path)
            }
            if itemValues.isSymbolicLink == true {
                symbolicLinks += 1
                continue
            }
            guard itemValues.isRegularFile == true else { continue }
            regularFiles += 1
            bytes += UInt64(max(itemValues.fileSize ?? 0, 0))
        }

        if let failedURL = enumerationError {
            throw ArtifactScannerError.unreadable(failedURL.path)
        }
    }

    return ArtifactComponent(
        name: url.lastPathComponent,
        kind: kind(for: url, isDirectory: values.isDirectory == true),
        path: relativePath(of: url, under: root),
        regularFileCount: regularFiles,
        symbolicLinkCount: symbolicLinks,
        totalBytes: bytes
    )
}

/// Path of `url` relative to the scan root, using `/` separators. Both
/// URLs come from the same enumerator, so the root is always a path
/// prefix; the fallback keeps the function total even for the root
/// itself or an unexpected layout.
private func relativePath(of url: URL, under root: URL) -> String {
    let rootPath = root.path
    let path = url.path
    if path == rootPath { return url.lastPathComponent }
    let prefix = rootPath.hasSuffix("/") ? rootPath : rootPath + "/"
    if path.hasPrefix(prefix) {
        return String(path.dropFirst(prefix.count))
    }
    return path
}

