/// Path of an enumerated item relative to the scan root, expressed as
/// the item's last `depth` path components joined with `/`. Deriving the
/// relative path from the enumeration depth (instead of stripping the
/// root's string prefix) stays correct when the root is reached through
/// a symlink and the enumerator vends resolved paths (e.g. /var ->
/// /private/var).
private func relativePath(of url: URL, depth: Int) -> String {
    url.pathComponents.suffix(max(depth, 1)).joined(separator: "/")
}

